-- Sequences
SELECT setval('users_user_id_seq', COALESCE((SELECT MAX(user_id) FROM users), 1));
SELECT setval('products_product_id_seq', COALESCE((SELECT MAX(product_id) FROM products), 1));
SELECT setval('product_variants_variant_id_seq', COALESCE((SELECT MAX(variant_id) FROM product_variants), 1));
SELECT setval('address_address_id_seq', COALESCE((SELECT MAX(address_id) FROM address), 1));
SELECT setval('orders_order_id_seq', COALESCE((SELECT MAX(order_id) FROM orders), 1));
SELECT setval('cart_cart_id_seq', COALESCE((SELECT MAX(cart_id) FROM cart), 1));

COMMIT;
