INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (7, 'MB.03 Lo', 'Basketball', 4760.00, 20, 'basketball7', 'Puma', 'shoe', 'เหาะไปกับ MB.03 Lo เทคโนโลยีโฟม NITRO™ และดอกยางที่ยึดเกาะได้ดีจะช่วยให้คุณทะยานขึ้นสู่ขอบห่วง ตาข่ายออกแบบพิเศษและแผ่นหุ้มส้นเท้า TPU จะมอบประสิทธิภาพระดับกาแลกซีให้กับคุณ');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (8, 'Scoot Zeros II', 'Basketball', 4200.00, 20, 'basketball8', 'Puma', 'shoe', 'Scoot Henderson เป็นนักบาสเกตบอลที่มีความคล่องตัวอย่างเหนือชั้น รองเท้า ซิกเนเจอร์รุ่น Scoot Zeros II ของเขา ถ่ายทอดแนวคิด O.D.D (Overly Determined to Dominate) ที่เป็นเอกลักษณ์ ผ่านดีไซน์สีสันสดใสและโดดเด่น เพื่อรองรับทั้งสมรรถนะและการมองเห็นในระดับสูงสุดบนสนามแข่งขัน');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (11, 'Predator Club', 'Football', 2000.00, 20, 'football1', 'Adidas', 'shoe', 'ค้นพบความแตกต่างระหว่างการมุ่งทำประตูและการรู้ว่าจะทำประตูได้ด้วยรองเท้าฟุตบอล adidas Predator ที่ได้รับการออกแบบมาเพื่อการทำประตูโดยเฉพาะ รองเท้าฟุตบอล Club คู่นี้มีอัปเปอร์วัสดุสังเคราะห์เคลือบพื้นผิว Strikeprint ที่ยึดเกาะได้ดีเพื่อการควบคุมบอลที่ดีขึ้น พื้นชั้นล่างอเนกประสงค์ได้รับการออกแบบมาเพื่อให้คุณอยู่ในตำแหน่งที่เหมาะสมในการยิงประตูบนสนามหญ้าธรรมชาติที่แห้ง สนามหญ้าเทียม และสนามดิน');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (12, 'F50 League', 'Football', 3200.00, 20, 'football2', 'Adidas', 'shoe', 'ค้นหาความเร็วเพื่อแสดงตัวตนของคุณอย่างแท้จริงในสนาม สัมผัสความเร้าใจในรองเท้าฟุตบอล adidas F50 ที่ออกแบบมาเพื่อความเร็ว รองเท้าฟุตบอล League คู่นี้โดดเด่นด้วยลายพิมพ์ Sprintgrid ที่สะดุดตา พร้อมด้วยอัปเปอร์ Fiberskin ที่ใช้คอรองเท้าทรงมิดคัทเพื่อการล็อคกระชับอย่างมั่นคง ชุดพื้นชั้นล่าง Sprintplate น้ำหนักเบา ช่วยให้วิ่งได้เร็วบนพื้นผิวหลายประเภท');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (13, 'Nike Phantom 6 Low Elite EA SPORTS FC', 'Football', 11000.00, 20, 'football3', 'Nike', 'shoe', 'ไม่ว่าจะอยู่ในสนามหรือออนไลน์ Phantom 6 Elite ก็แม่นยำจนน่าขนลุก เราใส่การปรับปรุงใหม่ๆ อย่าง Gripknit ระดับปฏิวัติวงการและแผ่นรองยึดเกาะ Cyclone 360 รองเท้าที่ช่วยยิงประตูได้อย่างแม่นยำคู่นี้เป็นเหมือนสูตรโกงสำหรับการแข่งขันครั้งต่อไป');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (14, 'Nike Tiempo Legend 10 Club', 'Football', 2100.00, 20, 'football4', 'Nike', 'shoe', 'ต่อให้เป็นตํานานก็ยังหาทางพัฒนาต่อได้ ไม่ว่าจะเพิ่งเริ่มต้นหรือแค่เล่นสนุก รองเท้าสตั๊ด Club รุ่นล่าสุดนี้ก็พร้อมพาคุณลงสนามโดยไม่ลดทอนคุณภาพลง หนังสังเคราะห์โอบรับรูปเท้าและไม่ยืดมากเกินไปเพื่อการควบคุมที่ดียิ่งขึ้น Legend 10 เบาและเพรียวกว่า Tiempo รุ่นไหนๆ ที่เคยมีมาจวบจนปัจจุบัน และเหมาะสําหรับใส่เล่นทุกตําแหน่งในสนาม ไม่ว่าจะส่งลูกฝ่ากองหลังอย่างแม่นยำหรือไล่ตามกองหลังเพื่อหยุดไม่ให้ฝั่งตรงข้ามได้บอลไป');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (15, 'KING ULTIMATE RE-CHARGE FG/AG', 'Football', 7500.00, 20, 'football5', 'Puma', 'shoe', 'ประกาศให้ทุกคนได้รู้ ราชาองค์ใหม่มาถึงแล้ว! รองเท้าฟุตบอลคู่นี้สมศักดิ์ศรีแห่งชื่อ “KING” ด้วยการผสานวัสดุ K-BETTER™ ที่ปราศจากส่วนประกอบจากสัตว์ และโครงสร้าง GRIPCONTROL 3D บริเวณด้านในของรองเท้า เพื่อเพิ่มประสิทธิภาพในการควบคุมลูกบอลอย่างเหนือชั้น ราชาองค์ใหม่ไม่ได้ถือกำเนิดขึ้นทุกวัน แต่วันนี้ ทายาทผู้ชอบธรรมได้ปรากฏกายแล้ว.');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (16, 'FUTURE 8 ULTIMATE FG/AG', 'Football', 6800.00, 20, 'football6', 'Puma', 'shoe', 'เพลย์เมกเกอร์ ปลดปล่อยความคิดสร้างสรรค์ของคุณบนสนามฟุตบอลที่มั่นคงด้วย FUTURE 8 ULTIMATE รองเท้าฟุตบอลที่เปลี่ยนเกมเหล่านี้มีตาข่ายความหนาแน่นสูงเพื่อการควบคุมลูกบอล พื้นรองเท้า FLEXGILITY เพื่อการเคลื่อนไหวที่คล่องตัว และตัวเลือกในการใส่โดยมีหรือไม่มีเชือกผูกรองเท้า เพื่อให้คุณสามารถเคลื่อนไหวไปมาระหว่างแดนและสร้างสรรค์สิ่งที่เหนือขีดจำกัด ความพอดีและประสิทธิภาพขั้นสุดของ PUMA รอคุณอยู่');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (20, 'Nike Dunk Low Retro Premium', 'Sneaker', 5200.00, 20, 'lifestyle1', 'Nike', 'shoe', 'เฉลิมฉลองความมั่นใจในการเป็นตัวของตัวเองด้วยคู่คลาสสิกจากปี 85 คุณจะสัมผัสถึงการรองรับและความสบายจากหนัง หนังกลับ และหนังสังเคราะห์ ซึ่งเป็นการผสมผสานของหนังวัสดุระดับพรีเมียมที่ชวนให้นึกถึงความหลากหลายที่พบได้ในร้านมือสองที่คุณชื่นชอบ สวมคู่นี้เพื่อให้ทุกคนรู้ว่าคุณเอาจริงในทุกๆ วัน');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (21, 'Nike Total 90', 'Sneaker', 4300.00, 20, 'lifestyle2', 'Nike', 'shoe', 'สไตล์ฟุตบอลของแท้ที่วันนี้ผลิตมาเพื่อสวมใส่ทุกวัน Total 90 กลับมาอีกครั้งและพาย้อนกลับไปยุค Y2K ด้วยส่วนบนบุควิลท์แบบออริจินัลและเชือกรองเท้าแบบอสมมาตร เราเปลี่ยนจากพื้นรองเท้ามีปุ่มสตั๊ดเป็นพื้นยางแบนที่พร้อมใส่ตะลุยท้องถนน และนำพาเลทสีในตำนานที่พร้อมให้คุณใส่ได้ทุกรูปแบบกลับมา');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (22, 'XLG MTW', 'Sneaker', 4700.00, 20, 'lifestyle3', 'Adidas', 'shoe', 'เข้าสู่ยุคใหม่ของสตรีทสไตล์ด้วย adidas XLG MTW รองเท้าที่ผสมผสานดีไซน์ล้ำสมัยและเทคโนโลยีการรองรับในหนึ่งเดียว ด้วยโครงสร้างที่โดดเด่น พร้อมทั้งฟีเจอร์ที่ตอบโจทย์ทั้งการใช้งานจริงและการมองดีไซน์แฟชั่น');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (23, 'Grand Court Cloudfoam Comfort', 'Sneaker', 2500.00, 20, 'lifestyle4', 'Adidas', 'shoe', 'หากคุณมีสนีกเกอร์ได้เพียงคู่เดียว ก็ต้องคู่นี้เลย รองเท้าอาดิดาส Grand Court พร้อมแถบ 3-Stripes สุดคลาสสิกคู่นี้จะช่วยให้สไตล์สนีกเกอร์ของคุณดูเท่และสบายตา ส่วนรับแรงกระแทก Cloudfoam Comfort ให้ความนุ่มสบายเป็นพิเศษที่ด้านใน สามารถจับคู่เข้ากับกางเกงขายาวตัวโปรดของคุณได้เพราะรองเท้าคู่นี้จะพาคุณตะลุยไปทุกที่');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (24, 'NEW BALANCE 530', 'Sneaker', 3900.00, 20, 'lifestyle5', 'NewBalance', 'shoe', 'รุ่น 530 กลับมาอีกครั้ง พร้อมเฉดสีใหม่อันโดดเด่นหลากหลายแบบ โดยได้รับแรงบันดาลใจจากรองเท้าวิ่งคลาสสิกของเรา ดีไซน์ถูกออกแบบให้ย้อนรำลึกถึงยุค 1990–2000 โดยเฉพาะพื้นรองเท้า ABZORB® อันเป็นเอกลักษณ์ในตำนาน แต่ละรุ่นมาพร้อมอัปเปอร์ตาข่ายที่ระบายอากาศได้ดี เพื่อความสดชื่นและความสบายสูงสุดในทุกย่างก้าว');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (25, 'NEW BALANCE Fresh Foam X 1080v13', 'Sneaker', 5550.00, 20, 'lifestyle6', 'NewBalance', 'shoe', 'หากเราสามารถผลิตรองเท้าวิ่งได้เพียงคู่เดียวก็คงจะเป็นรองเท้าวิ่งผู้หญิง NEW BALANCE Fresh Foam X 1080v13 การผสมผสานที่เป็นเอกลักษณ์ระหว่างความสบายที่เชื่อถือได้และประสิทธิภาพสูง มอบความคล่องตัวที่ใช้งานได้ทุกวันจนถึงวันแข่งขัน ระบบลดแรงกระแทกที่พื้นรองเท้าชั้นกลาง Fresh Foam X สร้างมาเพื่อการเปลี่ยนผ่านจากการลงสู่พื้นสู่การออกตัวอย่างราบรื่น ในขณะที่อัปเปอร์ผ้าตาข่ายด้านบนช่วยระบายอากาศและรองรับได้ดี');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (26, 'Nike Victori One', 'FlipFlops', 1100.00, 20, 'slipper1', 'Nike', 'shoe', 'Victori One คือรองเท้าแตะที่ขาดไม่ได้สำหรับกิจกรรมในแต่ละวันทั้งบนชายหาดและบนอัฒจันทร์ มาพร้อมการปรับปรุงที่เรียบง่ายแต่ไม่ได้ใส่มาเล่นๆ อย่างแถบคาดที่กว้างขึ้นและโฟมที่นุ่มขึ้น คุณจึงใส่ไปพักผ่อนได้อย่างง่ายดาย สวมเท้าแล้วปล่อยใจไปกับความสบายไม่รู้จบได้เลย');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (27, 'Jordan Franchise', 'FlipFlops', 1100.00, 20, 'slipper2', 'Nike', 'shoe', 'รองเท้าแตะคู่นี้ผลิตจากโฟมที่ทนทานแต่ยืดหยุ่น พร้อมรองรับทุกย่างก้าว ส่วนโค้งเล็กน้อยในแผ่นรองฝ่าเท้าช่วยให้รู้สึกกระชับพอดีเสมอ และยังมาพร้อม Jumpman ตรงกลางด้านหน้า คุณจึงอวดความภาคภูมิใจใน Jordan ได้');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (28, 'Island Club Adilette 22', 'FlipFlops', 2000.00, 20, 'slipper3', 'Adidas', 'shoe', 'คอลเลกชัน Island Club ชวนให้นึกถึงความรู้สึกในช่วงฤดูร้อนที่ไม่มีวันสิ้นสุด ให้ทุกวันเป็นเหมือนวันหยุดไม่ว่าจะอยู่ริมสระน้ำหรือที่ไหน ๆ ด้วยคอลเลกชันสุดเก๋แสนสดใสที่ผสานเฉดสีพาสเทลเข้ากับดีไซน์คัลเลอร์บล็อคสุดแจ่มในโทนสีเดียวกันตั้งแต่หัวจรดเท้า คอลเลกชันนี้จึงอัดแน่นด้วยบรรยากาศดี ๆ จากวันวาน');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (29, 'Adilette Comfort', 'FlipFlops', 1500.00, 20, 'slipper4', 'Adidas', 'shoe', 'รองเท้าแตะผู้ใหญ่ ADIDAS Adilette Comfort โดดเด่นด้วยแถบ 3-Stripes บริเวณอัปเปอร์พร้อมผลิตจากวัสดุที่เน้นความเบาและนุ่มสบาย พื้นรองเท้ามอบความมีน้ำหนักเบา ช่วยรองรับการก้าวเดินได้อย่างมีประสิทธิภาพ');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (30, 'Popcat 20', 'FlipFlops', 1600.00, 20, 'slipper5', 'Puma', 'shoe', 'ก้าวเข้าสู่ความคลาสสิกของ PUMA อย่างแท้จริงด้วย Popcat 20 ของเราที่มอบสไตล์ที่ไม่มีใครเทียบได้และความสบายสำหรับคนรุ่นต่อไป');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (31, 'Hypnotic', 'FlipFlops', 2600.00, 20, 'slipper6', 'Puma', 'shoe', 'เพลิดเพลินกับวันฤดูร้อนที่ไร้กังวลด้วยรองเท้าแตะ Hypnotic ที่ปรับโฉมรองเท้า Hypnotic คลาสสิกของเราด้วยส่วนบนแบบเปิดที่ระบายอากาศได้ดี เหมาะสำหรับวันแดดจัด ผสมผสานสไตล์และความสบายได้อย่างลงตัว');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (32, 'Nike Dunk Low Retro', 'Sneaker', 3700.00, 20, 'lifestyle9', 'Nike', 'show', 'Nike Dunk Low Retro สร้างสรรค์มาเพื่อคอร์ทพื้นไม้ แต่ก็เป็นที่นิยมในแนวสตรีท วันนี้กลับมาพร้อมส่วนหุ้มชั้นนอกเฉียบคมและสีสันประจำทีมแบบออริจินัล รองเท้าบาสเก็ตบอลรุ่นไอคอนคู่นี้ถ่ายทอดกลิ่นอายยุค 80 ด้วยหนังระดับพรีเมียมที่ส่วนบน ซึ่งนอกจากจะดูดีแล้วเวลาสวมใส่ยังรู้สึกดียิ่งกว่าเดิม นอกจากนี้ เทคโนโลยีรองเท้ายุคโมเดิร์นยังนำความสบายจากยุคเก่ามาสู่ยุคศตวรรษที่ 21 อีกด้วย');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (33, 'Air Jordan 1 Retro High OG Baroque Brown and Sail', 'Sneaker', 6600.00, 20, 'lifestyle10', 'Nike', 'show', 'AJ1 รุ่นนี้แปลงโฉมซิกเนเจอร์รุ่นแรกของ Mike ด้วยการผสมผสานสีสันที่สดใหม่ โดยมีวัสดุระดับพรีเมียม ระบบลดแรงกระแทกนุ่ม และส่วนหุ้มข้อบุนวมให้การรองรับแบบเต็มร้อยและเฉลิมฉลองให้กับรองเท้าอันเป็นจุดเริ่มต้นของทุกสิ่ง');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (34, 'Nike Air Max Plus By You', 'Sneaker', 6900.00, 20, 'lifestyle11', 'Nike', 'show', 'รองเท้าที่พิสูจน์แล้วว่าดีจริงคู่นี้กลับมาในสีโทนกลางหลายเฉดเพื่อสไตล์ที่หลากหลาย เพิ่มความเงางามเล็กน้อยด้วยตาข่ายเมทัลลิกที่ส่วนบนและตัวเลือกสีเหลือบมุกบนกรอบพลาสติก หลังจากเลือกป้ายลิ้นรองเท้าจาก 7 แบบแล้ว ปิดท้ายด้วยข้อความส่วนตัวที่ส่วน Air แต่ละข้าง Air Max Plus พร้อมให้คุณแต่งเติมลูกเล่นพิเศษเฉพาะตัวแล้ว');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (35, 'PREDATOR XLG', 'Sneaker', 5800.00, 20, 'lifestyle12', 'Adidas', 'show', 'เข้าสู่ยุคใหม่ของสตรีทสไตล์ด้วย adidas Predator XLG รองเท้า Lifestyle ที่ได้รับแรงบันดาลใจจากตำนานรองเท้าฟุตบอล Adidas Predator อันโด่งดัง ผสานการออกแบบที่ล้ำสมัยและโครงสร้างรองรับที่ใช้งานได้จริงในชีวิตประจำวัน');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (36, 'Adizero EVO SL', 'Sneaker', 5800.00, 20, 'lifestyle13', 'Adidas', 'show', 'สัมผัสประสบการณ์ความไวได้ใน Adizero Evo SL แรงบันดาลใจจากนวัตกรรมของรองเท้าระดับทำลายสถิติในตระกูลรองเท้าวิ่ง Adizero และโดยเฉพาะ Pro Evo 1 รองเท้า Evo SL ออกแบบมาเพื่อให้คุณใส่วิ่งและใส่ทำกิจกรรมอื่นได้ ผสานเทคโนโลยี Adizero เข้ากับความงดงามที่โดดเด่นและไม่เหมือนใครที่ได้แรงบันดาลใจจากรองเท้าวิ่งแข่ง จึงเป็นวิวัฒนาการแห่งความไวในทุกด้านของชีวิต ชั้นโฟม LIGHTSTRIKE PRO ที่ตอบสนองได้ดีในพื้นชั้นกลางจะมอบความสบายและการรับแรงกระแทกเพื่อการส่งคืนพลังอย่างเต็มประสิทธิภาพ');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (37, 'MR530 White with Natural Indigo', 'Sneaker', 3900.00, 20, 'lifestyle14', 'NewBalance', 'show', 'ดีไซน์ของรองเท้ารุ่นนี้ได้รับแรงบันดาลใจจากรองเท้าวิ่งคลาสสิกของเรา โดยมีการออกแบบที่ชวนให้หวนคิดถึงยุค 1990–2000 โดยเฉพาะพื้นรองเท้า ABZORB® ที่เป็นเอกลักษณ์เฉพาะตัว แต่ละรุ่นมาพร้อมอัปเปอร์ตาข่ายที่ระบายอากาศได้ดี เพื่อความสดชื่นและความสบายในทุกการสวมใส่');
INSERT INTO public.products (product_id, name, description, price, stock_quantity, image_filename, brand, category_name, detail) VALUES (38, '574v3 Nimbus Cloud', 'Sneaker', 3500.00, 20, 'lifestyle15', 'NewBalance', 'show', 'รุ่น 574 ถูกออกแบบมาให้เป็นรองเท้าที่ “เชื่อถือได้และทำได้ดีในทุกด้าน” มากกว่าจะเป็นรองเท้าที่เน้นเทคโนโลยีล้ำสมัยหรือใช้วัสดุระดับพรีเมียม ความเรียบง่ายและความอเนกประสงค์โดยไม่โอ้อวดนี้เอง คือสิ่งที่ผลักดันให้ 574 ก้าวขึ้นสู่สถานะ “ตำนาน” อย่างแท้จริง');
